-- Synthetic schema for the tests of the catalog scan. It belongs to no application.
-- Keys over one and several columns, foreign keys over one and several columns,
-- unique constraints, defaults, serial and identity numbering, and the common types.

create type order_state as enum ('new', 'paid', 'shipped');

create table customers (
  id serial primary key,
  email varchar(200) not null unique,
  name text,
  vip boolean not null default false,
  created_at timestamp with time zone not null default now(),
  birthday date,
  external_id uuid default gen_random_uuid(),
  preferences jsonb default '{}'::jsonb
);

create table products (
  sku varchar(32) primary key,
  title text not null,
  price numeric(10, 2) not null default 0,
  stock integer not null default 0 check (stock >= 0),
  views bigint,
  updated_at timestamp without time zone
);

create table orders (
  id bigint generated always as identity primary key,
  customer_id integer not null references customers (id) on delete cascade,
  state order_state not null default 'new',
  total numeric not null default 0,
  placed_on date not null default current_date
);

create table warehouses (
  region text,
  code text,
  label text not null,
  primary key (region, code),
  constraint warehouses_label_key unique (label)
);

create table stock_levels (
  region text not null,
  code text not null,
  sku varchar(32) not null references products (sku),
  quantity integer not null default 0,
  primary key (region, code, sku),
  constraint stock_levels_warehouse_fkey foreign key (region, code) references warehouses (region, code) on update cascade
);

create table order_lines (
  order_id bigint references orders (id),
  line smallint,
  sku varchar(32) not null references products (sku),
  quantity integer not null,
  primary key (order_id, line),
  unique (order_id, sku)
);

create table tags (
  id integer generated by default as identity primary key,
  label text not null
);

create index orders_customer_idx on orders (customer_id);
create unique index products_title_lower_idx on products (lower(title));
create index orders_open_idx on orders (placed_on desc) where state <> 'shipped';
